package com.chesspulseai.service; import com.chesspulseai.dto.ProbabilityResponse; import com.chesspulseai.enumtype.GameResult; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
/** Scores are normalized to White's perspective: positive centipawns mean White is better. */ @Service public class ProbabilityService { private final double threshold; public ProbabilityService(@Value("${chesspulse.probability.draw-display-threshold:0.5}")double threshold){this.threshold=threshold;} public ProbabilityResponse from(Integer cp,Integer mate){if(mate!=null)return mate>0?terminal(GameResult.WHITE_WIN):terminal(GameResult.BLACK_WIN);double score=cp==null?0:Math.max(-2000,Math.min(2000,cp));double whiteShare=1d/(1d+Math.exp(-score/260d));double draw=.08+.30*Math.exp(-Math.pow(score/240d,2));double decisive=1-draw;return distribution(decisive*whiteShare,draw,decisive*(1-whiteShare));} public ProbabilityResponse terminal(GameResult result){return switch(result){case WHITE_WIN->new ProbabilityResponse(100,0,0d);case BLACK_WIN->new ProbabilityResponse(0,100,0d);case DRAW->new ProbabilityResponse(0,0,100d);default->from(0,null);};} private ProbabilityResponse distribution(double white,double draw,double black){double w=round(white*100),d=round(draw*100),b=round(100-w-d);return new ProbabilityResponse(w,b,d>=threshold?d:0d);} private double round(double v){return Math.round(v*10d)/10d;}}
